() => {
  const hero = document.querySelector('main') ? null : null;
  // Find hero container - the generic after banner
  const body = document.body;
  // Let's get the top-level structure
  const children = Array.from(document.body.children);
  return children.map((c, i) => ({i, tag: c.tagName, cls: c.className, id: c.id})).slice(0,5);
}

