() => {
  const hero = document.body.children[1];
  const section = document.createElement('section');
  section.className = 'py-16 sm:py-20 border-t border-slate-200';
  section.setAttribute('data-injected', 'newsletter-below-hero');
  section.innerHTML = `
    <div class="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
      <div class="mx-auto max-w-3xl rounded-2xl border border-slate-200 bg-gradient-to-br from-white to-blue-50/60 p-8 sm:p-10 shadow-sm">
        <div class="max-w-xl">
          <span class="inline-block text-xs font-semibold uppercase tracking-wider text-blue-600">Newsletter</span>
          <h2 class="mt-2 text-2xl sm:text-3xl font-bold tracking-tight text-slate-900">Get BaroCSS updates in your inbox</h2>
          <p class="mt-2 text-slate-600">New features, examples, and runtime CSS tips—about once a month, no spam.</p>
          <form class="mt-6 flex flex-col sm:flex-row gap-3">
            <label for="hero-newsletter-email" class="sr-only">Email address</label>
            <input id="hero-newsletter-email" type="email" placeholder="you@example.com" class="w-full sm:flex-1 rounded-md border border-slate-300 bg-white px-3.5 py-2.5 text-sm text-slate-900 placeholder:text-slate-400 shadow-sm focus:outline-none focus:border-blue-600 focus:ring-2 focus:ring-blue-600/40 transition">
            <button type="button" class="inline-flex items-center justify-center px-5 py-2.5 rounded-md bg-blue-600 text-white font-medium text-sm shadow-sm hover:bg-blue-700 focus:outline-none focus:ring-2 focus:ring-blue-600/40 transition border border-transparent whitespace-nowrap">Subscribe</button>
          </form>
          <p class="mt-3 text-xs text-slate-500">We respect your privacy. Unsubscribe at any time.</p>
        </div>
      </div>
    </div>`;
  hero.insertAdjacentElement('afterend', section);
  return 'inserted';
}

() => {
  const s = document.querySelector('[data-injected="newsletter-below-hero"]');
  const card = s.querySelector('.rounded-2xl');
  const input = s.querySelector('input');
  const btn = s.querySelector('button');
  const form = s.querySelector('form');
  const g = el => getComputedStyle(el);
  return {
    cardBg: g(card).backgroundImage.slice(0,40),
    cardRadius: g(card).borderTopLeftRadius,
    cardPad: g(card).padding,
    formDisplay: g(form).flexDirection,
    inputBorder: g(input).borderColor,
    inputRadius: g(input).borderTopLeftRadius,
    btnBg: g(btn).backgroundColor,
    btnColor: g(btn).color,
    inputWidth: input.getBoundingClientRect().width,
    btnWidth: btn.getBoundingClientRect().width,
    sameRow: Math.abs(input.getBoundingClientRect().top - btn.getBoundingClientRect().top) < 5
  };
}

